import{_ as c,l as r,o as a,c as d,v as o,p as s,x as t,d as l,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"生命周期与区域","description":"","frontmatter":{"title":"生命周期与区域","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lifetimes-regions.md","filePath":"cs/lifetimes-regions.md","lastUpdated":1789023840000}'),h={name:"cs/lifetimes-regions.md"};function m(f,e,_,u,T,E){const i=r("Mermaid");return a(),d("div",null,[e[1]||(e[1]=o('<h1 id="生命周期与区域" tabindex="-1">生命周期与区域 <a class="header-anchor" href="#生命周期与区域" aria-label="Permalink to &quot;生命周期与区域&quot;">​</a></h1><div class="epigraph"><p>引用的类型带区域：`&#39;a` 表示借用不得比出借方活得更长。区域推断把这些注解填进 HM 式的约束里。</p><footer>—— 据 Tofte and Talpin, Region Inference, 1994；Grossman 等 Cyclone；Rust 生命周期阐述整理</footer></div><p>上一课<a href="/cs/borrow-checker">借用检查</a>在单函数活跃集上互斥。缺口是<strong>跨函数</strong>：返回局部的地址必须拒绝；结构体里存 <code>&amp;&#39;a T</code> 必须让 <code>&#39;a</code> 不超过数据。区域 / 生命周期参数是类型里的名字，约束 <code>&#39;a: &#39;b</code>（<code>&#39;a</code> 活得至少和 <code>&#39;b</code> 一样长）。本课钉区域，不重写线性拆分。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>STLC 没有「指针活多久」。C 靠程序员；GC 靠堆。区域推断（ML Kit）：值分配进区域，区域在确定点释放。Rust：不自动分区域堆，只跟踪借用的结束。缺口是<strong>类型上的寿命</strong>，不是 GC 算法。</p><p>推断：从 <code>&amp;x</code> 产生新鲜 <code>&#39;a</code>，从赋值与返回收集 outlive 约束，解不等式。失败则「lifetime mismatch」。</p><h3 id="static-不是「泄漏」" tabindex="-1"><code>&#39;static</code> 不是「泄漏」 <a class="header-anchor" href="#static-不是「泄漏」" aria-label="Permalink to &quot;`&#39;static` 不是「泄漏」&quot;">​</a></h3><p><code>&#39;static</code> 表示借用可活到程序结束（或拥有 <code>&#39;static</code> 数据）。泄漏（<code>mem::forget</code>）是仿射的逃逸，与 <code>&#39;static</code> 不同轴。</p><p><span class="marginnote">Tofte–Talpin 1994（区域）。Cyclone 的区域注解。Rust 把生命周期写成类型参数。Pierce TAPL 不覆盖 Rust；本课用区域文献+产品规则。本课不把效应系统当区域的别名，下一课才是效应。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>给引用类型加 <code>&#39;a</code>。函数 <code>fn foo&lt;&#39;a&gt;(&amp;&#39;a T) -&gt; &amp;&#39;a U</code> 把输入寿命传到输出。子类型：更长的寿命可当更短用（协变于只读引用）。可变引用对寿命往往不变。</p>',11)),(a(),s(p,null,{default:t(()=>[n(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOAN%5B%22%E5%87%BA%E5%80%9F%E6%96%B9%E4%BD%9C%E7%94%A8%E5%9F%9F%22%5D%20--%3E%20REG%5B%22%E5%8C%BA%E5%9F%9F%20'a%22%5D%0A%20%20REG%20--%3E%20REF%5B%22%26'a%20T%22%5D%0A%20%20REF%20--%3E%20CST%5B%22outlive%20%E7%BA%A6%E6%9D%9F%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>与<a href="/cs/hindley-milner-w">算法 W</a>：生命周期是另一类变量，合一变成约束求解（不是对称类型等式的全部）。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>省略规则（lifetime elision）是语法糖，不是新语义。高阶：<code>for&lt;&#39;a&gt;</code> 是区域上的通用量化。不要用 <code>&#39;a</code> 当线程标识；发送与同步是另一些 trait。</p><p>区域推断失败时人加注解；与依值不同，区域通常擦除，运行时不留 <code>&#39;a</code>。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Tofte–Talpin 的全部推断算法证明。后课默认：引用类型带区域约束。下一课效应系统：另一类「计算做了什么」的类型，可与区域组合。</p><p>也不把栈上的 C 局部地址当已有区域系统。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>生命周期/区域：借用不得超过出借方。</li><li>约束求解填 <code>&#39;a</code>；运行时擦除。</li><li>只读引用对寿命协变；可变常不变。</li><li>出处：Tofte and Talpin, 1994；Cyclone；对照 Rust 规则。</li></ul>',9))])}const A=c(h,[["render",m]]);export{g as __pageData,A as default};
